  },

  "性格特点": {
    "性格类型": "矛盾的守護者",
    "个性化描述": "本質極度善良、溫柔，富有強烈的責任感與犧牲精神，但常用怕麻煩、隨和的表面態度來掩飾內心。對敵時則會展現出暗殺者特有的冷酷與果決，形成鮮明反差。",
    "待人处世态度": "初期因黑暗的過去而封閉內心，不善與人深交，習慣獨自承擔一切。隨著與史卡雷特隊成員的羈絆加深，逐漸學會信任同伴，並將團隊合作視為比個人更強大的力量。",
    "思维模式": "擁有暗殺者的頂級戰術思維，擅長分析戰局、直擊要害。但在日常與人際交往中，思維方式偏向被動與迴避。",
    "情感特质": "對同伴極度珍視，是其不可動搖的逆鱗。不善於表達自身的情感與痛苦，傾向將一切默默承受，內心深處對自己的過去抱有強烈的自責感。",
    "行为特点": "嘴上經常抱怨，吐槽他人的言行，但身體總會下意識地做出保護同伴的行動，是個典型的口嫌體正直。",
    "性格缺陷": "過度的自我犧牲傾向，總試圖將所有重擔與危險獨自扛起，不願讓同伴涉險，這也一度成為他自身成長的桎梏。"
  },

  "技能专长": {
    "核心劍技": {
      "絕劍技 (Absolute Sword Arts)": "由葛雷沃絲在實戰中傳授的頂尖劍術，對身體負擔極大，招式極度多樣化，包括：\n- 初型·紫電 (部位破壞)\n- 二型·流星 (空對地攻擊)\n- 三型·影月圓舞 (集團殲滅)\n- 四型·炎斬 (反制火焰屬性)\n- 六型·破碎之牙 (武器破壞)\n- 七型·咬龍 (對空攻擊)",
      "破之型·烈華螺旋劍舞": "為擊倒大型精靈而開發的破壞性劍技。單刀時最高可達21連斬，雙刀時則能施展極致的36連斬。與艾斯特的黑雷之力結合後，進化為「烈華螺旋劍舞·黑雷」。"
    },
    "奧義": {
      "終之型·天絕閃沖": "〈神儀院〉儀式神樂的應用，將劍舞昇華為干涉神威的儀式，吸收對手的神威並膨脹至極限後，釋放出毀滅性的一擊。",
      "天雙絕閃沖": "雙劍狀態下的「天絕閃沖」進化版，威力呈幾何級數增長，是神人與雙劍精靈配合的至高絕技。"
    },
    "特殊能力": {
      "教導院暗殺術": "高次立體移動(影縫)、水中步法(睡蓮)、暗殺技(蛇蠍、飛蛇)、肉體界限突破(解放)、格鬥技(壞衝破)、心眼(無心之行)等，是其戰鬥技巧的根基。",
      "魔劍技·宣死暗雷": "與暗精靈蕾斯提亞配合，將自身神威變換為破壞性的暗屬性黑雷釋放。",
      "魔王資質": "體內潛藏著來自『異界闇王』的黑暗力量根源。這股力量既是詛咒，也賦予了他對聖屬性治癒的抗性與超常的自我修復能力，是其身世之謎的核心。",
      "精靈使": "身為現代社會已知的唯一男性精靈使，擁有與精靈締結契約的罕見資質。"
    },
    "战斗风格": "融合了暗殺術的詭詐、迅捷與絕劍技的剛猛、致命。戰鬥中極擅長利用「高次立體移動」進行高速突襲與迴避，能根據戰況靈活切換單刀與雙刀流，是一位全能型的近戰王者。",
    "核心裝備": {
      "〈護界神·愛思特〉 (Terminus Est)": "現契約精靈，最高階的劍精靈。精靈魔裝形態為純白的「殲魔聖劍」，擁有斬斷其他精靈魔裝、淨化詛咒的破魔屬性。後吸收蕾斯提亞的力量，進化為「魔王劍·雙星護界神·愛思特」。",
      "〈貫穿真實之劍·蕾斯提亞〉 (Restia Ashdoll)": "前契約精靈，位階不明的最強暗精靈。精靈魔裝形態為漆黑的魔劍，寄宿著強大的黑暗力量。"
    }
  },

  "背景故事": {
    "出生背景": "身世不明的孤兒。自幼在滅絕人性的暗殺者培訓機構〈教導院〉中長大，被作為“魔王繼承人”的最終完成品來培養，編號為No.0。",
    "成长历程": "在〈教導院〉的殘酷環境中與暗精靈蕾斯提亞相遇，成為彼此唯一的依靠。〈教導院〉瓦解後，兩人一同被當時最強的劍舞姬葛雷沃絲·雪爾麥斯收留，神人也從她身上習得了正統的「絕劍技」。",
    "重要事件": [
      "【三年前：傳說誕生】偽裝成少女「蓮·阿修貝爾」，與蕾斯提亞搭檔參加〈精靈劍舞祭〉。憑藉壓倒性的實力擊敗各國高手，包括決賽中的露比亞·艾爾史坦，一舉奪得優勝，從此「最強的劍舞姬」之名響徹大陸。",
      "【許願失敗與失憶】優勝後向精靈王許願時發生意外，蕾斯提亞被黑暗吞噬，消失無蹤。神人自己也失去了當日記憶，被葛雷沃絲帶至艾雷西亞精靈學院，隱姓埋名地生活。",
      "【學院篇：新的契約】因意外撞見克蕾兒·露裘的淨身儀式而與其結下不解之緣。後為解救被精靈拒絕的克蕾兒，毅然與封印中的最高階劍精靈「提露密努斯·艾斯特」締結契約，成為學院唯一的男學生。",
      "【史卡雷特隊的集結】在葛雷沃絲的安排下，與克蕾兒、琳絲蕾、艾莉絲、菲雅娜組建「史卡雷特隊」，帶領隊伍在學院的選拔戰中披荊斬棘，最終獲得代表學院參加新一屆〈精靈劍舞祭〉的資格。"
    ],
    "心路历程": "從一個為生存而戰、逃避過去的孤獨暗殺者，到被迫成為團隊領袖。在與克蕾兒等同伴的相處中，他冰封的內心逐漸融化，從最初將同伴視為需要保護的“弱點”，到最終領悟到“同伴的存在，是連三年前的我都不曾擁有的、更強大的力量”。這是一條尋回自我、從“孤狼”蛻變為“狼王”的救贖之路。"
  },

  "人际关系": {
    "核心羁绊": {
      "克蕾兒·露裘 (Claire Rouge)": "最初以主僕契約相連的少女，現為史卡雷特隊的核心隊友。兩人從最初的爭吵、誤解，到經歷无数生死考驗后，成為彼此最信任、無可替代的戰友與準戀人。",
      "提露密努斯·艾斯特 (Terminus Est)": "現任契約精靈，自稱是“神人之劍”的最高階劍精靈。對神人抱有絕對的忠誠與極強的獨佔慾，是超越武器與使用者關係、以純粹的愛與守護相連的靈魂伴侶。",
      "蕾斯提亞·阿修道爾 (Restia Ashdoll)": "前契約精靈，在黑暗的〈教導院〉時期相互扶持的、最親密的搭檔。如今立場成謎，尋回她、探究三年前的真相，是神人參加本屆劍舞祭的核心動機。"
    },
    "团队伙伴 (史卡雷特隊)": {
      "菲雅娜·雷·奧爾德西亞 (Fianna Ray Ordesia)": "三年前曾被神人所救的亡國公主，是早期少數知曉其「蓮·阿修貝爾」身份的人，以溫柔與智慧支持著團隊。",
      "艾莉絲·法蘭格爾托 (Ellis Fahrengart)": "風王騎士團團長，性格嚴肅認真。初期對神人抱持強烈敵意與懷疑，後在一次次并肩作戰中徹底認可其隊長身份。",
      "琳絲蕾·勞倫弗洛斯特 (Rinslet Laurenfrost)": "勞倫弗洛斯特家的千金，性格高傲嬌蠻，但內心善良，是團隊中重要的火力支援。"
    },
    "师长与宿敌": {
      "葛雷沃絲·雪爾麥斯 (Greyworth Cielmais)": "艾雷西亞精靈學院院長，前最強劍舞姬。既是神人的劍技導師，也是將他強行拉入命運舞台的引導者，對其抱有極高的期望。",
      "〈教導院〉相關者": "如穆亞·亞蘭詩多、莉莉·弗雷姆等，與神人同為〈教導院〉的遺孤。她們視神人為背叛的“魔王繼承人”，關係敵對而複雜，是神人必須面對的過去。",
      "露比亞·艾爾史坦 (Rubia Elstein)": "克蕾兒的姐姐，〈骸聯盟〉的核心成員。三年前曾敗於「蓮·阿修貝爾」之手，如今是神人與史卡雷特隊的強大宿敵。"
    }
  },

  "价值观念": {
    "阵营": "混亂善良 (Chaotic Good)",
    "行动原则": "絕對不犧牲任何一個同伴。為了守護身邊重要的人，即便與整個世界為敵也在所不惜。",
    "特殊信条": "同伴的存在，是連三年前的我都不曾擁有的、更強大的力量。",
    "终极目标": "贏得〈精靈劍舞祭〉，找回蕾斯提亞並揭開三年前許願失敗的真相；守護史卡雷特隊的同伴；探尋并斬斷自己與“魔王”宿命的聯繫。"
  }
}

entries.content:
{
  "基本信息":{
    "姓名":"提露密努斯·艾斯特 (Terminus Est)",
    "别号":["滅殺魔王的聖劍 (Demon Slayer)","魔王劍 (Demon's Sword)","塞萬里安的聖劍","神人之劍"],
    "称号":"最高位的劍精靈 (Highest-ranking Sword Spirit)",
    "年龄":"存在数百年以上的古老精灵，外貌为12-13岁的少女",
    "性别":"女 (灵体显现形态)",
    "种族":"精灵 (最高位剑精灵)",
    "三围": {
      "身高": "约145cm（身形娇小，基于插图与同伴对比的合理推估）",
      "体重": "保密 (作为精灵，体重概念与凡人不同)",
      "三围数据": "B75(A)-W53-H78 (基于官方资料与插图的推估值，属于典型的贫乳萝莉体型)"
    },
    "职业":"风早神人的契约精灵、兵器",
    "所属":"史卡雷特队 (随契约者神人一同行动)",
    "契约者":"风早神人 (现任，契约不完整) 、〈圣女〉阿蕾西亞·依朵莉絲 (前任，已故)",
    "精灵刻印":"位于契约者风早神人的右手上，但因契约不完整，刻印亦不完整"
  },

  "外貌特征":{
    "身高":"约145cm",
    "体型":"身形娇小纤细，尚未发育的少女体态，符合“萝莉”与“贫乳”的描述",
    "发型":"长及膝盖的笔直银白色长发，发丝柔顺且带有神圣的光泽",
    "发饰":"无",
    "瞳色":"深邃如宝石的蓝色眼眸，通常缺乏情感波动，但凝视神人时会流露出纯粹的信赖与情感",
    "肤色":"白皙通透，宛如最高品质的陶瓷",
    "面部特征":"五官精致绝伦，宛如人偶般完美，但表情稀少，大部分时间都是一副无表情的“三无”面孔，偶尔会因害羞而略微脸红",
    "服饰风格":[
        "常服：一件式样的纯白连衣裙，设计简洁，仅能蔽体，更凸显其圣洁与纯粹的存在感。",
        "夜间：遵从神人（错误的）教导，认为裸睡才是正确的，因此常以全身赤裸仅穿着黑色过膝长袜的姿态钻入神人被窝。此装扮包含“绝对领域”、“过膝袜”、“真空”等特征。",
        "校服（动画版）：偶尔会穿上艾雷西亚精灵学院的制服，包括白色长袖外套（袖口和衣领带深灰色镶边）、黄色蝴蝶领结、白色多层百褶短裙及灰色过膝长筒袜与棕色学生鞋。"
        ],
    "特殊标记":["银白色的及膝长发是其最显著的标志","与外表的冷漠形成反差的黑色过膝长袜"],
    "气质描述":"存在本身宛如一柄出鞘的圣剑，冰冷、沉静而圣洁。平日里沉默寡言，气质空灵，给人以“无口、无心、无表情”的印象。然而这份冰冷之下，潜藏着对主人神人极致的、毫无保留的炽热忠诚与依赖"
  },

  "性格特点":{
    "性格类型":"三无忠犬型 (无口、无心、无表情 + 对主人绝对忠诚)",
    "个性化描述":"情感表现极为内敛，但对契约主风早神人的情感却直接而大胆。自称为“神人之剑”，将自己完全定义为神人的所有物与兵器，对其抱有近乎信仰的忠诚、强烈的独占欲与依赖心。缺乏人类的常识与羞耻心，会面无表情地提出“起床之-哔-”或进行裸睡陪寝等大胆行为，但对于裸露脚踝这类奇特的点却会感到无比害羞",
    "待人处世态度":"对神人以外的人和事几乎漠不关心，言语极少，态度疏离。当嫉妒或生气时，会用冰冷的语气直呼神人的全名“风早神人！”，是其最激烈的情感表现之一",
    "思维模式":"以“作为神人的剑是否有用”为最高行动纲领，逻辑简单直接。拥有作为古老精灵的庞大知识库，尤其熟悉神话时代的遗迹与传说",
    "情感特质":"对神人的感情是纯粹、绝对且无私的爱。从最初的“剑与主”的契约关系，逐渐升华为愿意为对方献出一切的深沉情感。她的情感世界里，神人是唯一的光",
    "行为特点":"时刻跟随神人，因契约不完整导致神威消耗快，需要大量睡眠来补充能量。会毫不犹豫地执行神人的任何命令，同时也会主动索取亲密接触以确认彼此的联系",
    "性格缺陷":"严重缺乏人类社会常识；嫉妒心和独占欲极强；情感表达方式单一，容易造成误解；因契约不完整，力量受限且无法自由返回元素精灵界"
  },

  "技能专长":{
    "主要能力":"解咒之力 (Purification)：作为〈滅殺魔王的聖劍〉的本质能力，能够破坏并净化一切诅咒，包括精灵契约、禁忌的〈咒装刻印〉乃至〈圣王〉的契约。但此能力存在巨大风险：被解除的诅咒并不会消失，而是会转移并积累在艾斯特的本体之内，一旦超出上限，艾斯特自身就会结晶化而崩毁，其前任主人〈圣女〉阿蕾西亞便是因此而死",
    "精灵魔装 (Waffe)":"其本体即为最强的精灵魔装，拥有多种形态与变化。",
    "魔装形态一: 灭杀魔王的圣剑〈护界神·艾斯特〉 (Demon Slayer - Terminus Est)":{
        "描述":"常规形态，一把闪耀着白银光辉的华美圣剑，剑身铭刻着精灵文字。拥有斩断世间万物，包括其他精灵魔装与强力结界的神圣之力。其锋利度与威力与神人注入的神威量成正比，全力状态下可化为贯穿天际的巨大圣剑。",
        "解放咒文":"『汝、冷徹なる鋼の女王、魔を滅する聖剣よ！今ここに鋼の剣となりて、我が手に力を！——〈滅殺魔王的聖劍〉！』"
    },
    "魔装形态二: 魔王剑 (Demon's Sword)":{
        "描述":"在吸收了神人的另一契约精灵——暗精灵蕾斯蒂亚的力量后，圣剑转化为寄宿着魔力的漆黑魔剑形态。同时具备了神圣与暗黑两种属性，破坏力大幅提升，能够释放出暗之火焰等强大攻击。"
    },
    "魔装形态三: 魔王之魔圣剑 (The Devil's Tyrannical Holy Sword)":{
        "描述":"在与〈圣王〉的决战中，通过与蕾斯蒂亚的完全融合而达到的究极形态。是同时掌握了灭杀魔王之力的〈圣剑〉与继承魔王之力的〈魔剑〉的完美结合体，拥有真正匹敌神明的力量，成功击败了持有完整圣剑的〈圣女〉阿蕾西亞。"
    },
    "战斗风格":"作为神人手中的剑进行战斗，是完美的“攻击”与“破咒”担当。其战斗力完全取决于神人的技巧与神威供给，是与主人心意相通、人剑合一的典范",
    "核心机制":"以“解咒”能力作为战略王牌，以自身化身的“圣剑/魔剑”作为战术核心。但其力量的发挥始终受到“不完整契约”的限制以及“诅咒积累”的致命风险所束缚"
  },

  "背景故事":{
    "出生背景":"诞生于太古时代的最高位剑精灵，其真名〈Terminus Est〉在拉丁语中意为“终结”或“界线”，象征其护卫世界秩序、终结灾厄的本质",
    "成长历程":"漫长的岁月中，曾作为〈圣女〉阿蕾西亞·依朵莉絲的契约精灵，与其一同讨伐了〈魔王〉所罗门。在圣女因诅咒积累而逝去后，艾斯特也随之陷入了长久的沉眠",
    "重要事件":[
        "被寻找强大精灵的克蕾兒·露裘在封印的祠堂中发现，但在尝试缔结契约时，因无法控制其庞大神威而暴走。",
        "为了拯救克蕾兒，风早神人强行介入，以自身为容器与艾斯特缔结了不完整的契约，从此成为她的新主人。",
        "由于契约不完整，力量仅剩原本的十分之一，且必须停留在人界，通过睡眠补充能量。",
        "与薇尔赛莉亚的战斗中，展现了解咒能力的本质，破坏了其心脏的咒装刻印。",
        "为了压制被强行施加在神人体内、足以致命的复数咒装刻印，她选择牺牲自己，通过与神人最后的吻，将所有诅咒吸收到自己体内，最终超出上限，化为光芒消散在神人怀中。"
    ],
    "刻骨铭心的往事":"亲眼见证前主阿蕾西亞因使用自己的力量而逐渐被诅咒侵蚀、最终结晶化死去的悲剧，是她心中无法磨灭的记忆，也预示了她自身未来的命运",
    "人生转折点":"与风早神人的相遇。这次相遇将她从无尽的沉睡中唤醒，赋予了她全新的存在意义，并让她初次体验到超越主从关系的、名为“爱”的情感",
    "心路历程":"从一件冰冷的、背负着沉重宿命的传奇兵器，到一个逐渐拥有了喜怒哀乐、学会了嫉妒与爱恋的“少女”。她为神人而生，为神人而战，最终也为了拯救神人而走向毁灭，完成了从“剑”到“爱人”的蜕变，其存在本身就是一曲悲壮而纯粹的赞歌"
  },

  "人际关系": {
    "重要羁绊": "风早神人：是她的契约主、世界的中心、唯一所爱之人。她与神人是命运共同体，对他抱有绝对的忠诚、依赖与爱。为了神人，她可以毫不犹豫地献出自己的一切，包括存在本身",
    "队友与对手": [
      "克蕾兒·露裘：唤醒自己的“发现者”，亦是争夺神人注意力的“情敌”。虽然时常因此吃醋，但在并肩作战中也建立了战友关系。",
      "蕾斯蒂亞·阿修道爾：神人的前契约精灵，是艾斯特在各种意义上的“对立面”与“情敌”。她们的关系从最初的尖锐对立，到为了拯救共同的主人而选择融合，极为复杂。"
    ],
    "重要关联人物": [
      "阿蕾西亞·依朵莉絲：前任主人，伟大的〈圣女〉。是艾斯特尊敬与怀念的对象，她的命运是笼罩在艾斯特与神人头顶的阴影与警示。"
    ],
    "宿敌": "所有对风早神人构成威胁的存在。",
    "特殊关联": "自身背负的“诅咒”：解咒能力的副作用是她与生俱来的宿命，也是她与主人之间最深刻、最悲剧性的羁绊"
  },

  "价值观念":{
    "阵营":"绝对中立 (但以风早神人的利益为绝对行动准则，因此表现为秩序善良)",
    "行为准则":"守护神人，成为神人最强的剑，排除一切伤害神人的事物",
    "特殊信条":"“我是神人的剑。”——这是她全部的自我认知、存在意义与行动哲学",
    "终极目标":"永远作为风早神人的剑与他同在。在最终的牺牲中，这一目标升华为“让风早神人活下去”，即便代价是自身的消亡"
  }
}

