{
  "基本信息": {
    "姓名": "格雷瓦丝·雪露麦斯 (Greyworth Cielmais)",
    "别号": [
      "黄昏魔女 (The Twilight Witch)",
      "大陆最强精灵使 (Continent's Strongest Spirit User)"
    ],
    "称号": "前帝国十二骑将首席、兰巴尔战争英雄、精灵剑舞祭优胜者",
    "年龄": "39岁",
    "性别": "女",
    "种族": "人类 (精灵使)",
    "三围": {
      "身高": "身形高挑，具体数据不详",
      "体重": "不详",
      "三围数据": "B110(M)-W62-H90 (成年时期，基于插画的目测推估值)"
    },
    "职业": "阿蕾西娅精灵学院学院长兼暗部最高长官",
    "所属": "奥地西亚帝国、阿蕾西娅精灵学院",
    "契约精灵": "魔精灵〈迪斯•帕德〉(原)、魔精灵〈弗拉德•德拉库〉(被操控期间)",
    "精灵刻印": "位于心脏部位的“咒装刻印”"
  },
  "外貌特征": {
    "常态 (成年)": {
      "发型": "一头极长的银灰色长发，长度及腰或更长，有时会盘起或扎成高马尾，两侧有发束垂于胸前",
      "瞳色": "红色（亦有灰色之说）",
      "肤色": "白皙",
      "面部特征": "容貌美艳，充满了成年女性的成熟魅力。神情时常透露出严厉与高傲，佩戴着一副单片眼镜",
      "服饰风格": "偏爱红色高领外套或长袍，内搭黑色的V领低胸上衣或连衣裙，脖子上佩戴着黑色颈圈（Choker）",
      "特殊标记": [
        "单片眼镜"
      ],
      "气质描述": "散发着霸道、精明且深不可测的气场，仿佛一切尽在掌握之中。既是充满魅惑的成熟女性，也是身经百战的冷酷将领"
    },
    "年轻时期 (15岁)": {
      "发型": "极长的浅色直发，长度及臀，头上佩戴着一个浅色发箍",
      "体型": "身形修长，富有少女感（B78-W55-H80，基于插画的推估值）",
      "服饰风格": "身穿深色的无袖连衣裙，外搭一件领口系有蝴蝶结的浅色短袖披肩，脚穿长度及大腿的深色长筒袜",
      "特殊标记": [
        "持有一把结合了长剑与钢笔外形的奇特武器"
      ],
      "气质描述": "表情平静而严肃，在少女的青涩中已展露出超凡脱俗的天赋与气场"
    }
  },
  "性格特点": {
    "性格类型": "霸道导师型 & 冷酷谋略家",
    "个性化描述": "表面毒舌霸道，尤其喜欢用言语和行动调侃、捉弄风早神人。然而在处理正事或面对敌人时，则会展现出极致的狠辣与果断，下手毫不留情，是一位善于操纵人心的女强人",
    "待人处世态度": "作为学院长和前帝国将领，她极度关心帝国与学生的未来。她是一位深谋远虑的布局者，为了达成终极目标，不惜将包括自己在内的所有人视为棋子，利用一切可用的资源",
    "思维模式": "拥有极高的战略眼光和政治手腕，能够洞察事件背后的真相并布下跨越数年的长远棋局，思考方式以结果为导向，冷酷且高效",
    "情感特质": "内心深处对风早神人怀有类似母亲的关爱与师徒之情，将其视为自己意志与计划的继承者。因二十四年前许下的愿望，一直背负着沉重的责任与良心的谴责",
    "行为特点": "行事雷厉风行，无论是严酷地教导神人，还是亲自出手清除叛徒，都展现出无与伦比的决断力",
    "性格缺陷": "为了达成“创造没有战乱的世界”这一宏大目标，可以变得非人般的冷酷，不惜牺牲少数甚至自我牺牲。对力量的执着使她选择了以生命为代价的“咒装刻印”，凸显其为达目的不惜一切的极端面"
  },
  "技能专长": {
    "主要能力": "【绝剑技 (Absolute Sword Technique)】：继承自雪露麦斯家族的至高剑技，并在此基础上开创了究极奥义。",
    "自创奥义": "【绝剑技奥义·终之型『天绝闪冲』(Tenzen Senkouzan)】：格雷瓦丝自创的绝剑技最强奥义，后传授给风早神人。",
    "特殊能力": "【咒装刻印 (Curse Seal Crest)】：为摆脱与圣王的契约而在心脏烙上的禁忌刻印。能让她在超过精灵使黄金年龄后，依旧强行维持全盛时期的力量，但其反噬会不断侵蚀生命，最终导致神威经络断绝。",
    "契约精灵": {
      "原契约精灵": "魔精灵〈迪斯•帕德〉(Demon Spirit 'Dis Pater')，别名〈冥府伯爵〉。曾为魔王所罗门役使的七十二柱精灵之一，是最强的魔精灵之一。在格雷瓦丝神威经络断绝后失去联系。",
      "临时契约精灵": "魔精灵〈弗拉德•德拉库〉(Demon Spirit 'Vlad Dracul')。在被米涅亚操控期间缔结契约的公爵级最高位魔精灵，外形为人形，能够与人类正常交流，极为罕见。"
    },
    "精灵魔装 (Waffe)": {
      "原精灵魔装": "〈兴风者〉(Storm Bringer)：由〈迪斯•帕德〉转化而成的黑色单刃剑，外形与蕾斯蒂亚的〈贯穿真实之圣剑〉相似。",
      "临时精灵魔装": "〈吸血魔剑〉(Vampiric Demon Sword)：由〈弗拉德•德拉库〉转化的血红色魔剑。拥有吸收血液后成长的诡异能力，同时能分化出巨大的狼型魔兽进行协同攻击。"
    },
    "战斗风格": "以臻于化境的“绝剑技”与驾驭最强魔精灵的压倒性力量进行正面歼灭。无论是作为剑士还是精灵使，她都曾是立于大陆顶点、令所有敌人闻风丧胆的存在。",
    "核心机制": "通过心脏的“咒装刻印”，以燃烧生命为代价，强行突破肉体与年龄的限制，发挥出超越巅峰的战斗力。这是一种以毁灭自身为前提的、悲壮而强大的力量体系。"
  },
  "背景故事": {
    "出生背景": "奥地西亚帝国的贵族，雪露麦斯家族的成员。该家族背景神秘，疑似为传说中的剑圣艾布黎尔·雪露麦斯的后裔。",
    "成长历程": "天资卓绝，年仅15岁时便赢得精灵剑舞祭的优胜。之后加入帝国军，晋升为“十二骑将”首席，在第二次兰巴尔战争中立下赫赫战功，被公认为“大陆最强精灵使”，是所有姬巫女憧憬的传奇人物。",
    "重要事件": [
      "二十四年前，向精灵王许下“创造一个没有战乱的世界”的愿望，并因此与当时的圣王结盟，为其寻找并觉醒暗之精灵王的继承人。",
      "在一次暗杀事件中，以压倒性实力击败了作为暗杀者的风早神人。此后对其产生兴趣，以解放蕾斯蒂亚为条件将其收为“女仆”，并以极其严酷的方式向其传授“绝剑技”，塑造了他的人生观。",
      "因察觉到圣王计划的危险性并出于良心谴责，她通过在心脏烙上“咒装刻印”的方式，强行解除了与圣王的契约，但也因此失去了部分关键记忆。",
      "在精灵剑舞祭决赛前，将绝剑技最终奥义“天绝闪冲”传授给神人，随后因刻印反噬耗尽力量，神威经络断绝。",
      "帝国内乱期间，被圣女派系的米涅亚控制，重获力量并与神人两度交战。最终被打下悬崖后恢复记忆。",
      "恢复后，率领师生夺回被占领的学院，并向神人等人坦白了所有真相，获得了神人的理解，被其视为母亲般的存在。",
      "在最终决战中，为掩护神人而与其他强者联手，牵制并击杀了地之精灵王的替身。"
    ],
    "刻骨铭心的往事": "二十四年前向精灵王许下的愿望，是她一生行动的根源与背负的罪责。这个愿望让她与圣王结盟，也让她走上了培养神人觉醒为“魔王”的道路，此间的内心挣扎与良心谴责是她最沉重的负担。",
    "人生转折点": "与风早神人的相遇。神人不仅是她计划中最关键的棋子，更成为了她冰冷谋划中唯一的情感寄托，是她计划的继承者，也让她在冷酷的伪装下保留了人性中的温情。",
    "心路历程": "从一个期望终结战争的年轻英雄，转变为一个为了实现理想而不惜背负骂名、牺牲一切的冷酷谋略家。在引导神人的过程中，她扮演了严师、导师乃至母亲的角色，最终在坦白一切后，从长达二十四年的沉重枷锁中获得了解脱与救赎。"
  },
  "人际关系": {
    "重要羁绊": "风早神人：是她的剑术弟子、前“女仆”、人生导师下的学生，也是她计划的继承者与类似养子的存在。她塑造了神人的剑与战斗的意义，两人的关系超越了普通的师生情谊，是交织着利用、期盼、守护与亲情的复杂羁绊。",
    "重要关联人物": [
      "圣王：曾是格雷瓦丝为实现理想而结盟的对象，后因理念不合与对其计划的怀疑而决裂，是她一切谋划的根源与最终的对手。",
      "米涅亚·圣汀：在帝国内乱中操控了格雷瓦丝的枢机卿，使其一度成为神人的敌人。",
      "蕾斯蒂亚·阿修道尔：格雷瓦丝以解放她为条件，开启了与神人的缘分。她是串联起格雷瓦丝与神人过去的关键存在。",
      "帝国十二骑将：她曾经领导的帝国最强骑士团。在帝国内乱中，部分成员的叛变使他们从同僚变为敌人。"
    ],
    "宿敌": "以圣王为首的、企图按自身意愿扭曲世界的势力。",
    "特殊关联": "雪露麦斯家族：其姓氏暗示了她与传说中的剑圣艾布黎尔·雪露麦斯存在血缘关系，这或许是她超凡剑技天赋的来源。"
  },
  "价值观念": {
    "阵营": "混乱中立 (Chaotic Neutral)",
    "行为准则": "为实现“世界和平”的崇高目标，可以采用包括欺骗、利用、牺牲在内的任何手段。将最终结果的“善”置于过程的“正义”之上，是一位彻底的马基雅维利主义者。",
    "特殊信条": "“为了守护，不惜毁灭。”——无论是毁灭敌人，还是毁灭自己。她用自己的生命践行着守护的承诺，即便那意味着踏上修罗之道。",
    "终极目标": "修正自己过去因天真愿望而引发的世界扭曲，引导风早神人走向正确的强者之路，并以自己的方式，终结世间一切战乱，实现最初的愿望。"
  }
}

